head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF21300.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    chb_Grp_All_1.setValue(1);
    chb_Grp_All_2.setValue(1);
    scwin.fn_allCheck_1();
    scwin.fn_allCheck_2();

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var comNm = $c.stf.getObjectValue(txb_COM_NM_1);
        var secuGrpId = "";
        if ($c.stf.getObjectValue(chb_Grp_St_1) == 'Y') secuGrpId += 'ST,DR,FS,IF,';
        if ($c.stf.getObjectValue(chb_Grp_Mf_1) == 'Y') secuGrpId += 'MF,';
        if ($c.stf.getObjectValue(chb_Grp_Sc_1) == 'Y') secuGrpId += 'SC,';
        if ($c.stf.getObjectValue(chb_Grp_Rt_1) == 'Y') secuGrpId += 'RT,';
        if ($c.stf.getObjectValue(chb_Grp_All_1) == 'Y') secuGrpId = '';
        //if (getObjectValue(chb_Grp_All_1) =='Y')		secuGrpId = 'ST,DR,FS,IF,MF,SC,RT';  

        var url = "/ListedSearch.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listStockTradingSuspension&inputMessageId=LISTED_SEARCH_TRD_HALT_OUT";
        url += "&gubun=1";
        url += "&comNm=" + comNm.replace("&", "＆");
        url += "&secuGrpId=" + secuGrpId;
        url += "&kindCd=" + $c.stf.getObjectValue(rdo_STKCERT_KIND_CD);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var comNm = $c.stf.getObjectValue(txb_COM_NM_2);
        var secuGrpId = "";
        if ($c.stf.getObjectValue(chb_Grp_St_2) == 'Y') secuGrpId += 'ST,DR,FS,IF,';
        if ($c.stf.getObjectValue(chb_Grp_Mf_2) == 'Y') secuGrpId += 'MF,';
        if ($c.stf.getObjectValue(chb_Grp_Sc_2) == 'Y') secuGrpId += 'SC,';
        if ($c.stf.getObjectValue(chb_Grp_Rt_2) == 'Y') secuGrpId += 'RT,';
        if ($c.stf.getObjectValue(chb_Grp_All_2) == 'Y') secuGrpId = '';
        //if (getObjectValue(chb_Grp_All_2) =='Y')		secuGrpId = 'ST,DR,FS,IF,MF,SC,RT';  
        var url = "/ListedSearch.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listStockTradingSuspension&inputMessageId=LISTED_SEARCH_TRD_HALT_OUT";
        url += "&gubun=2";
        url += "&comNm=" + comNm.replace("&", "＆");
        url += "&secuGrpId=" + secuGrpId;
        url += "&startDate=" + $c.stf.getObjectValue(edt_SDate);
        url += "&endDate=" + $c.stf.getObjectValue(edt_EDate);
        url += "&depCd=" + $c.stf.getObjectValue(cmb_TeamList);
        url += "&empNo=" + $c.stf.getObjectValue(cmb_EmpList);
        url += "&listStatCd=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD);
        url += "&rsnCd=" + $c.stf.getObjectValue(txb_LD_HALT_RSN_CD);
        url += "&kindCd=" + $c.stf.getObjectValue(rdo_STKCERT_KIND_CD2);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_GetParRsnCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "06";
    arrPar[2] = txb_LD_HALT_RSN_CD; // 코드값을 포함할 컨트롤
    arrPar[3] = txb_LD_HALT_RSN_NM; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParRsnCd = function(arrPar) {
    txb_LD_HALT_RSN_CD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_LD_HALT_RSN_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};
scwin.fn_allCheck_1 = function() {
    var checkArray = [chb_Grp_St_1, chb_Grp_Mf_1, chb_Grp_Sc_1, chb_Grp_Rt_1];
    if (chb_Grp_All_1.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_allCheck_2 = function() {
    var checkArray = [chb_Grp_St_2, chb_Grp_Mf_2, chb_Grp_Sc_2, chb_Grp_Rt_2];
    if (chb_Grp_All_2.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.img_COM_NM_1_onclick = function() {
    //IsurcdSearch(txb_ISUR_CD_1, txb_COM_NM_1);
    $c.cm.IsurcdSearch(txb_COM_NM_1, txb_COM_NM_1);
};
scwin.img_COM_NM_2_onclick = function() {
    $c.cm.IsurcdSearch(txb_COM_NM_2, txb_COM_NM_2);
};
scwin.img_LD_HALT_RSN_CD_onclick = async function() {
    scwin.fn_GetPar = fn_GetParRsnCd;
    scwin.fn_SetPar = fn_SetParRsnCd;
    await $c.frame.CreateDialogFrame("DLG_IND_SEL", "/listingcommon/ULDSTF92007.gfm", "코드선택", 10, 10, 515 + 5, 315 + 30, "window");
};
scwin.btn_Search_1_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Search_2_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var Rows;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        Rows = dts_List_1.getTotalRow();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        Rows = dts_List_2.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
    //fn_list_sync();

};
scwin.chb_Grp_All_1_onclick = function() {
    scwin.fn_allCheck_1();
};
scwin.chb_Grp_St_1_onclick = function() {
    chb_Grp_All_1.setValue(0);
};
scwin.chb_Grp_Mf_1_onclick = function() {
    chb_Grp_All_1.setValue(0);
};
scwin.chb_Grp_Sc_1_onclick = function() {
    chb_Grp_All_1.setValue(0);
};
scwin.chb_Grp_Rt_1_onclick = function() {
    chb_Grp_All_1.setValue(0);
};
scwin.chb_Grp_All_2_onclick = function() {
    scwin.fn_allCheck_2();
};
scwin.chb_Grp_St_2_onclick = function() {
    chb_Grp_All_2.setValue(0);
};
scwin.chb_Grp_Mf_2_onclick = function() {
    chb_Grp_All_2.setValue(0);
};
scwin.chb_Grp_Sc_2_onclick = function() {
    chb_Grp_All_2.setValue(0);
};
scwin.chb_Grp_Rt_2_onclick = function() {
    chb_Grp_All_2.setValue(0);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.txb_LD_HALT_RSN_CD_onblur = function() {
    if (txb_LD_HALT_RSN_CD.getValue() == "") {
        txb_LD_HALT_RSN_NM.setValue("");
    }
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "현재 매매거래정지내역", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "매매거래정지내역", "", "8");
    }
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top_1);
    $c.cm.PanelToGroupBox(panel_Top_2);
    MaxTab_01.setSelectedTabIndex(1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    scwin.fn_list_sync();
};
